"""One-time migration of the supplied HTML, preserving the five original game sections.
Not needed to run the app. The authoritative original stays in reference/original.html.
"""
from pathlib import Path
import re
ROOT=Path(__file__).resolve().parents[1]
original=(ROOT/'reference/original.html').read_text()
