original_games='<!-- Original five game sections, retained and upgraded. -->'+original_games
original_games=original_games.replace('<div class="rl-wheel" id="rl-wheel"><div id="rl-nums"></div></div>','<div class="rl-wheel" id="rl-wheel"></div>')
original_games=original_games.replace('        <div class="rl-hub">♠</div>','')
