original_games=original_games.replace('Drop multiple balls at once if you\'re feeling lucky. Every bounce is a coin flip.','Twelve preselected left/right decisions. Up to eight balls in play; each has its own stake.')
original_games=original_games.replace('<h3>Paytable (× bet)</h3>','<h3>The golden paytable</h3><p class="panel-caption">Total returns, including your stake.</p>')
original_games=original_games.replace('<h3>Jacks or Better (× bet)</h3>','<h3>Jacks or Better</h3><p class="panel-caption">Total returns, including your stake.</p>')
original_games=original_games.replace('💎💎💎','<span data-pay-symbol="diamond"></span>').replace('🔔🔔🔔','<span data-pay-symbol="bell"></span>').replace('🍒🍒🍒','<span data-pay-symbol="cherry"></span>').replace('🍋🍋🍋','<span data-pay-symbol="lemon"></span>')
original_games=original_games.replace('★ GOLDEN 777 ★','GOLDEN 777').replace('★ Blackjack pays 3 to 2 · Dealer stands on 17 ★','BLACKJACK PAYS 3 TO 2 · DEALER STANDS ON ALL 17s')
original_games=original_games.replace('The Wheel','The European wheel').replace('Betting Board — click a cell to place your chip','Make your play')
original_games=original_games.replace('<div class="bj-msg"','<div role="status" aria-live="polite" class="bj-msg"').replace('<div class="slot-result"','<div role="status" aria-live="polite" class="slot-result"').replace('<div class="vp-msg"','<div role="status" aria-live="polite" class="vp-msg"').replace('<div class="rl-result"','<div role="status" aria-live="polite" class="rl-result"')
# Add consistent rules affordance without replacing existing gamebar markup.
for game in ['blackjack','roulette','slots','poker','plinko']:
 start=original_games.index(f'<section id="view-{game}"')
 end=original_games.find('</section>',start)+len('</section>')
 section=original_games[start:end]
 section=section.replace('</h2>\n  </div>',f'</h2><button class="text-btn rules-trigger" data-rules="{game}"><span data-icon="info"></span> How to play</button>\n  </div>',1)
 section=section.replace('<section ', '<section aria-label="'+{'blackjack':'Blackjack','roulette':'European Roulette','slots':'Golden 777 Slots','poker':'Video Poker','plinko':'Plinko'}[game]+'" ',1)
 original_games=original_games[:start]+section+original_games[end:]
# Blackjack's original table and controls remain, with a useful side guide.
a=original_games.index('  <div class="felt">')
b=original_games.index('</section>',a)
block=original_games[a:b]
original_games=original_games[:a]+'''  <div class="bj-layout"><div class="table-column">'''+block+'''</div><aside class="panel game-guide"><span class="eyebrow">THE ORIGINAL CLASSIC</span><h3>A perfect twenty-one.</h3><p>The closest hand to 21 wins. Go over, and the house takes the round.</p><div class="guide-line"><span>Natural blackjack</span><b>3:2 profit</b></div><div class="guide-line"><span>Standard win</span><b>1:1 profit</b></div><div class="guide-line"><span>Equal hands</span><b>Stake returned</b></div><div class="guide-divider"></div><p class="small">Six-deck shoe. Dealer stands on soft 17. Double on your first two cards. No splits or insurance.</p><p class="small muted">Tap chips to add to your wager. A new hand never resets your wallet.</p></aside></div>\n'''+original_games[b:]

def gamebar(id,title,sub):
 return f'''<div class="gamebar"><button class="btn ghost sm" data-view="lobby"><span data-icon="back"></span> Lobby</button><h2>{title}<span class="sub">{sub}</span></h2><button class="text-btn rules-trigger" data-rules="{id}"><span data-icon="info"></span> How to play</button></div>'''

def bet(prefix,action):
 return f'''<div class="bet-module" id="{prefix}-bet-module"><label for="{prefix}-stake" class="field-label">YOUR STAKE <span>CHIPS</span></label><div class="stake-field"><span data-icon="chip"></span><input id="{prefix}-stake" type="number" inputmode="decimal" min="10" max="1000000" step=".01" value="25" aria-label="Stake in play-money chips"><button data-adjust="half" aria-label="Halve stake">½</button><button data-adjust="double" aria-label="Double stake">2×</button></div><div class="quick-stakes"><button data-stake="10">10</button><button class="selected" data-stake="25">25</button><button data-stake="100">100</button><button data-stake="500">500</button></div></div><button class="btn full" id="{prefix}-start">{action} <span data-icon="arrow"></span></button>'''

def result(prefix,text):
 return f'<div class="round-message" id="{prefix}-result" role="status" aria-live="polite">{text}</div>'

